using System;
using System.Numerics;
using System.Runtime.CompilerServices;
using Falcon;

namespace LauncherTest;

[Component("LauncherTest.Marker")]
public struct Marker
{
    public float Age;
}

// Test game: three entities of its own component, a sphere, and every root mesh rising.
public sealed class LauncherTestGame : Game
{
    private Query? _movers, _markers;

    [ModuleInitializer]
    internal static void Register() => Register<LauncherTestGame>();

    public override void OnStart()
    {
        _movers = new Query(Query.InOut<WorldTransform>(), Query.In<MeshInstance>(), Query.Not<Parent>(), Query.Not<RigidBody>());
        _markers = new Query(Query.InOut<Marker>());
        for (int i = 0; i < 3; ++i)
            Ecs.Set(Ecs.Create(), new Marker());
        Physics.Spawn(BodyShape.Sphere, new Vector3(0, 30, 0), new Vector3(0.3f, 0, 0), Vector3.Zero, Vector3.One);
    }

    public override void OnUpdate(float dt)
    {
        PerformanceHud.Update(dt);
        foreach (Chunk c in _movers!)
        {
            Span<WorldTransform> t = c.Write<WorldTransform>(0);
            for (int i = 0; i < c.Count; ++i)
            {
                Vector3 p = t[i].Position;
                p.Y += 0.5f;
                t[i].Position = p;
            }
        }
        foreach (Chunk c in _markers!)
        {
            Span<Marker> m = c.Write<Marker>(0);
            for (int i = 0; i < c.Count; ++i)
                m[i].Age += dt;
        }
    }
}

